!function(){function t(t){return function(t){if(Array.isArray(t))return a(t)}(t)||function(t){if("undefined"!=typeof Symbol&&null!=t[Symbol.iterator]||null!=t["@@iterator"])return Array.from(t)}(t)||function(t,d){if(t){if("string"==typeof t)return a(t,d);var e={}.toString.call(t).slice(8,-1);return"Object"===e&&t.constructor&&(e=t.constructor.name),"Map"===e||"Set"===e?Array.from(t):"Arguments"===e||/^(?:Ui|I)nt(?:8|16|32)(?:Clamped)?Array$/.test(e)?a(t,d):void 0}}(t)||function(){throw new TypeError("Invalid attempt to spread non-iterable instance.\nIn order to be iterable, non-array objects must have a [Symbol.iterator]() method.")}()}function a(t,a){(null==a||a>t.length)&&(a=t.length);for(var d=0,e=Array(a);d<a;d++)e[d]=t[d];return e}System.register(["./index-legacy-C_nr1GkG.js"],function(a,d){"use strict";var e,r,i,n,o,p;return{setters:[function(t){e=t.G,r=t.c,i=t.a,n=t.b,o=t.o,p=t._}],execute:function(){var d=document.createElement("style");d.textContent=".article-content[data-v-785fdb23]{max-width:800px;margin:0 auto;padding:24px 16px;color:#333;line-height:1.8}.article-content h2[data-v-785fdb23]{font-size:22px;margin:24px 0 12px}.article-content h3[data-v-785fdb23]{font-size:17px;margin:20px 0 8px}.article-content p[data-v-785fdb23]{margin:8px 0}.article-content ul[data-v-785fdb23]{padding-left:20px;margin:8px 0}.article-content ul li[data-v-785fdb23]{margin:4px 0}.article-content table[data-v-785fdb23]{width:100%;border-collapse:collapse;margin:12px 0}.article-content th[data-v-785fdb23],.article-content td[data-v-785fdb23]{border:1px solid #ddd;padding:8px 12px;text-align:left}.article-content th[data-v-785fdb23]{background:#f5f5f5;font-weight:600}\n/*$vite$:1*/",document.head.appendChild(d);var f={class:"article-content"};a("default",p(e({__name:"article",setup:function(a){return function(a,d){return o(),r("div",f,t(d[0]||(d[0]=[i("<h2 data-v-785fdb23>分贝测试工具说明</h2><p data-v-785fdb23>分贝测试工具借助麦克风实时测量环境声压等级，用环形仪表 + 频谱分析 + 时序波形三种可视化呈现。读数为近似 SPL，可校准 offset 让其更贴合真实分贝。</p><h3 data-v-785fdb23>三种实时可视化</h3><table data-v-785fdb23><thead data-v-785fdb23><tr data-v-785fdb23><th data-v-785fdb23>视图</th><th data-v-785fdb23>看什么</th><th data-v-785fdb23>用法</th></tr></thead><tbody data-v-785fdb23><tr data-v-785fdb23><td data-v-785fdb23>环形仪表</td><td data-v-785fdb23>当前瞬时响度（0–120 dB），按等级染色</td><td data-v-785fdb23>一眼判断&quot;吵不吵&quot;</td></tr><tr data-v-785fdb23><td data-v-785fdb23>频谱条</td><td data-v-785fdb23>不同频率上的能量分布</td><td data-v-785fdb23>区分低频轰鸣、人声、高频尖锐</td></tr><tr data-v-785fdb23><td data-v-785fdb23>时序波形</td><td data-v-785fdb23>最近 30 秒的响度曲线</td><td data-v-785fdb23>看声音的起伏与峰值时刻</td></tr></tbody></table><h3 data-v-785fdb23>噪声等级速查</h3><ul data-v-785fdb23><li data-v-785fdb23><strong data-v-785fdb23>0-30 dB</strong>：极安静（听阈下限、深夜室内、树叶沙沙）</li><li data-v-785fdb23><strong data-v-785fdb23>30-50 dB</strong>：安静（图书馆、安静办公室）</li><li data-v-785fdb23><strong data-v-785fdb23>50-60 dB</strong>：一般（普通对话、办公室环境）</li><li data-v-785fdb23><strong data-v-785fdb23>60-70 dB</strong>：较吵（街道、商店环境）</li><li data-v-785fdb23><strong data-v-785fdb23>70-85 dB</strong>：很吵（地铁、繁忙交通）</li><li data-v-785fdb23><strong data-v-785fdb23>85 dB</strong>：OSHA/NIOSH 推荐的 8 小时职业暴露上限，每升高 3 dB 安全暴露时间减半</li><li data-v-785fdb23><strong data-v-785fdb23>100 dB</strong>：安全暴露 ≤ 15 分钟（地铁列车进站）</li><li data-v-785fdb23><strong data-v-785fdb23>110 dB</strong>：安全暴露 ≤ 1.5 分钟（摇滚演唱会前排）</li><li data-v-785fdb23><strong data-v-785fdb23>120+ dB</strong>：瞬时即可造成永久性听力损伤（飞机起飞）</li></ul><h3 data-v-785fdb23>用什么算法</h3><ul data-v-785fdb23><li data-v-785fdb23>时域采样 → RMS（均方根）→ dBFS（满刻度分贝）→ 加 offset 映射到近似 SPL</li><li data-v-785fdb23>频域用 FFT（Web Audio AnalyserNode，2048 fftSize），按对数频率分布重采样到 56 根柱</li><li data-v-785fdb23>显示用低通滤波平滑，避免抖动；峰值保持以 10 dB/秒衰减</li><li data-v-785fdb23>默认 offset 0 dB（按 -100 dBFS → 0 dB SPL 线性映射），可手动 ±30 dB 调整</li></ul><p data-v-785fdb23>本工具仅供日常参考与相对对比。涉及法律、医学、职业健康的精确测量请使用专业声级计。</p><h3 data-v-785fdb23>使用场景</h3><ul data-v-785fdb23><li data-v-785fdb23><strong data-v-785fdb23>邻里噪音取证</strong>：怀疑楼上施工/装修/广场舞超标时记录峰值与时段，作为协商或投诉的辅助参考。</li><li data-v-785fdb23><strong data-v-785fdb23>办公/学习环境评估</strong>：比较咖啡馆、自习室、家中不同房间的环境响度，挑出最适合专注的位置。</li><li data-v-785fdb23><strong data-v-785fdb23>设备风扇/异响诊断</strong>：对比电脑、空调、风扇、抽油烟机等设备开关时的相对响度，定位最吵的设备。</li><li data-v-785fdb23><strong data-v-785fdb23>演出/会议现场参考</strong>：检查会议室麦克风音量是否合适，演出中粗略观察前后排响度差异。</li><li data-v-785fdb23><strong data-v-785fdb23>听力健康自查</strong>：提醒长时间暴露在 ≥85 dB 环境下的潜在听力风险。</li></ul>",11),n("h3",{itemscope:"",itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[n("span",{itemprop:"name"},"显示的分贝值准吗？")],-1),n("div",{itemscope:"",itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[n("p",{itemprop:"text"},"不是专业级的绝对值。浏览器拿不到麦克风的灵敏度参数，不同手机/电脑读数能差 ±20 dB 以上。本工具显示的是近似 SPL，主要用途是相对响度对比（同一台设备比较 A 和 B 哪个更吵）和趋势观察（声音随时间的变化）。需要法律级证据请使用专业声级计。")],-1),n("h3",{itemscope:"",itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[n("span",{itemprop:"name"},"怎么校准让读数更接近真实分贝？")],-1),n("div",{itemscope:"",itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[n("p",{itemprop:"text"},'页面下方"快速校准"按钮：在你认为接近 30 dB（深夜室内）/ 45 dB（图书馆）/ 60 dB（普通对话）/ 70 dB（街道）的环境点击对应按钮，工具会自动调整 offset 使当前读数对齐。也可拖 Offset 滑块手动调 ±30 dB。校准值存在浏览器本地，下次自动加载。')],-1),n("h3",{itemscope:"",itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[n("span",{itemprop:"name"},"为什么打不开麦克风？")],-1),n("div",{itemscope:"",itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[n("p",{itemprop:"text"},"NotAllowedError 表示权限被拒绝；NotFoundError 表示没有可用麦克风设备；NotReadableError 表示麦克风被其他程序占用；SecurityError 多半是非 HTTPS 或隐私模式禁用麦克风；AbortError 启动被中断点重试即可。iOS Safari 需 14.3+。")],-1),n("h3",{itemscope:"",itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[n("span",{itemprop:"name"},"处理的音频会上传吗？")],-1),n("div",{itemscope:"",itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[n("p",{itemprop:"text"},"不会。所有信号分析在浏览器本地完成（Web Audio API），麦克风采集 → AnalyserNode → 屏幕显示，全程不出本机。切走标签页、最小化、关闭页面都会立刻停止麦克风轨道。")],-1),n("h3",{itemscope:"",itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[n("span",{itemprop:"name"},"国家/地方对噪声有什么规定？")],-1),n("div",{itemscope:"",itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[n("p",{itemprop:"text"},"GB 3096-2008《声环境质量标准》把区域分 5 类——0 类（康复疗养区）昼 50 / 夜 40 dB；1 类（居住区）昼 55 / 夜 45 dB；2 类（混合区）昼 60 / 夜 50 dB；3 类（工业区）昼 65 / 夜 55 dB；4 类（交通干线两侧）昼 70 / 夜 55-60 dB。投诉时按所在区类对应限值核对。")],-1)])))}}}),[["__scopeId","data-v-785fdb23"]]))}}})}();
